#!/bin/sh
# Source checks of the B6b acceptance rules that only a board could exercise.
F=${1:-$(dirname "$0")/../09_guardian/09_guardian.ino}
fail=0
chk() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fail=1; fi; }
chk "A2 weights CRC checked at boot, guardian refuses to run on mismatch" "grep -q 'modelOk = hg2_check_crc();' '$F' && grep -A1 'if (!modelOk) {' '$F' | grep -q 'hg_fw_minute_inputs('"
chk "A2 CRC failure screen text (Σφάλμα μοντέλου)"                       "grep -q 'xce\\\\xa3\\\\xcf\\\\x86\\\\xce\\\\xac\\\\xce\\\\xbb\\\\xce\\\\xbc\\\\xce\\\\xb1' '$F'"
chk "A3 InternalFS.format() only in the 0.9.12 FS-HEAL ladder (2nd InternalFS fault in a row; profile backed up and rewritten)" "[ \$(grep -c 'InternalFS\\.format(' '$F') -eq 1 ] && grep -q 'ok = InternalFS.format(); InternalFS.begin(); }' '$F' && grep -q 'bool ps = prof && profileSave();' '$F'"
chk "A3 twin saved only from the nightly hook or a PROFILE write"        "[ \$(grep -c 'twinSave(\"' '$F') -eq 2 ] && grep -q 'twinSave(\"nightly\")' '$F' && grep -q 'twinSave(\"profile\")' '$F'"
chk "A4 hg_guardian_step called only through hg_fw_minute (once per minute)" "! grep -q 'hg_guardian_step(' '$F'"
chk "power: no expf/powf/logf in the sketch"                              "! grep -Eq '\\b(expf|powf|logf)\\(' '$F'"
chk "frozen sources compiled only through fz_ wrappers"                   "! ls \$(dirname '$F')/*.c | grep -v -E '/(fz_|hg_fw|hg_i2c|hg_ppg|hg_bootguard|log_ring)' | grep -q ."
chk "B1 every sketch file starts with the no-fast-math header (check_nofastmath.sh, source part)" "sh \$(dirname \"\$0\")/check_nofastmath.sh \$(dirname '$F') >/dev/null"
chk "M3 console profile does not re-initialise the guardian"            "! grep -q 'hg_guardian_init(' '$F' && grep -q 'hg_fw_apply_profile(&G' '$F'"
chk "M1 low battery keeps a soft haptic tick (never silent): boot vibrate() and the 0.9.17 sequencer (soft flag on every pattern)" "grep -q 'if (lowBatMode || pofHold) pat = PAT_SOFT;' '$F' && ! grep -q 'if (!hasDrv || lowBatMode || pofHold) return;' '$F' && grep -q 'static bool hapSoftNow() { return lowBatMode || pofHold' '$F' && grep -q 'UiMsg m = { UM_HAP, id, (uint8_t)hapSoftNow(), 0, 0 };' '$F'"
chk "M2 HELP can be cancelled on the band (long press -> ack type 3)"   "grep -q 'c.ack_type = 3; c.alarm_id = G.help_id;' '$F'"
chk "0.9.7 eco opcodes 0x16-0x1A parsed before the frozen hg_cmd_parse" "awk '/static void handleFrame/{f=1} f&&/hg_eco_cmd_parse\\(/{e=NR} f&&/hg_cmd_parse\\(p, n/{c=NR; exit} END{exit !(e && c && e < c)}' '$F'"
chk "0.9.7 board B: D0 is never assigned, D9 only as the dummy MISO" "! grep -Eq '=[[:space:]]*D0\\b' '$F' && [ \$(grep -Ec '=[[:space:]]*D9\\b' '$F') -eq 1 ] && grep -q 'SPI_DUMMY_MISO = D9' '$F'"
chk "0.9.17 one version: HG_FW_SHORT 0.9.17(-demo[-b7[u|n|s|t|f|g]]), INFO 0x0917, HG_FW_VERSION built from HG_FW_SHORT" "[ \$(grep -c '#define HG_FW_SHORT' '$F') -eq 1 ] && grep -Eq 'HG_FW_SHORT   \"0.9.17(-demo(-b7[unstfg]?)?)?\"' '$F' && grep -q 'HG_FW_NUM     0x0917' '$F' && ! grep -q '0.9.16\"' '$F'"
chk "0.9.10 FS-HEAL: our __assert_func (no silent spin) + FS deadline timer + GPREGRET2 marker read at boot" "grep -q 'extern \"C\" void __assert_func' '$F' && grep -q 'hgFsDie(HG_CAUSE_ASSERT, fsOp)' '$F' && grep -q 'fsDogTimer.begin(250, fsDogCb)' '$F' && grep -q 'healMarkerReg = hg_mk_pick(gpregret2Read(), &NI.mk' '$F'"
chk "0.9.10 FS-HEAL: every log write/remove goes through the guarded helpers (no bare logFS.remove, fileAppend always names its file id)" "! grep -n 'logFS.remove(' '$F' | grep -v 'return logFS.remove(path)' | grep -q . && ! grep -E 'fileAppend\([^)]*\)' '$F' | grep -v 'HG_FID_' | grep -v 'static bool fileAppend' | grep -q ."
chk "0.9.10 FS-HEAL: the live events log is the generation file, never events.txt / events2.txt" "grep -q 'fileAppend(evPath, (const uint8_t\*)jEv, n, HG_FID_EVENTS)' '$F' && ! grep -q 'fileAppend(\"/log/events' '$F'"
chk "0.9.13 FS-HEAL: heal state in .hg_noinit + a raw reserved flash page (no file system), log-area format only through healFormat / format YES" "grep -q 'memcpy(&NI.hs, &HS, sizeof HS)' '$F' && grep -q 'healPageWrite(HEAL_PAGE + slot \* HEAL_SLOT, buf, HEAL_SLOT)' '$F' && ! grep -q 'f.open(\"/fsheal.bin\"' '$F' && [ \$(grep -c 'logFS.format()' '$F') -eq 3 ]"
chk "0.9.9 the band's guardian haptic comes only from the rules layer (CHECK/DANGER/HELP passed through there); 0.9.17 through the sequencer" "grep -q 'ladderApply(&lo, hpFromFrozen(ALO.haptic, o));' '$F' && ! grep -q 'hpFromFrozen(o->haptic' '$F' && ! grep -q 'hapticStart(' '$F'"
chk "0.9.9 the rules layer only reads the guardian (no step, no command, no button, const output)" "! grep -Eq 'hg_guardian_(step|cmd|init)\(|hg_fw_button\(|hg_fw_minute\(' \$(dirname '$F')/hg_fw_alert.c && grep -q 'const hg_minute_out_t \*o;' \$(dirname '$F')/hg_fw_alert.h"
chk "0.9.9 the planner runs only through the validity gate" "grep -q 'hg_al_plan_minute(&AL, &ALO, &PL, &in, &o)' '$F' && ! grep -q 'hg_plan_minute(&PL' '$F'"
chk "0.9.7 planner never shows a nudge over a warning (warning input + nudge only on the OK screen)" "grep -q 'in->warning = (FW.minutes && FW.last_out.state != HG_ST_OK)' '$F' && grep -q 'scr == HG_SCR_OK && PL.active' '$F'"
chk "0.9.8 Her Day opcodes 0x1B/0x1C go through the same pre-frozen hg_eco_cmd_parse (range up to HG_CMD_VISIT)" "grep -q 'p\[0\] > HG_CMD_VISIT) return 0' \$(dirname '$F')/hg_fw_eco.c && grep -q 'case HG_CMD_DAY_PLAN: dayPlanItem(e)' '$F' && grep -q 'case HG_CMD_VISIT: visitRx(e)' '$F'"
chk "0.9.8 BLE: 2 peripheral links, STATUS + EVENTS notified per connection" "grep -q 'Bluefruit.begin(HG_MAX_LINKS, 0)' '$F' && grep -q '#define HG_MAX_LINKS 2' '$F' && grep -q 'hgStatus.notify(h, st, 20)' '$F' && grep -q 'hgEvents.notify(h, f, 20)' '$F' && ! grep -q 'hgEvents.notify(f, 20)' '$F'"
chk "0.9.8 N3 SHUTTERS is gone from the planner" "! grep -q 'return HG_N_SHUTTERS' \$(dirname '$F')/hg_fw_eco.c"
chk "0.9.12 every InternalFS file op is guarded with an ifs file id (same or previous line) and the flash-error hook is in" "awk '/File f\\(InternalFS\\)/ { if (\$0 !~ /FsGuard g\\(/ && p1 !~ /FsGuard g\\(/ && p2 !~ /FsGuard g\\(/) bad=1 } { p2=p1; p1=\$0 } END { exit bad }' '$F' && grep -q '__wrap_flash_nrf5x_event_cb' '$F' && [ \$(grep -c 'f.truncate(0)' '$F') -eq 2 ]"
chk "0.9.14 log writes run in the writer task: flushCore only from wrTaskFn (or setup before it starts), loop-side log commands refuse while it is busy" "[ \$(grep -c 'flushCore(' '$F') -eq 3 ] && grep -q 'xTaskCreate(wrTaskFn, \"logw\"' '$F' && grep -q 'if (wrBusy) return;                      // 0.9.14: the dump pauses' '$F' && [ \$(grep -c '# BUSY: the log writer' '$F') -ge 6 ]"
chk "0.9.14 the writer never drains the PPG FIFO or touches evBuf/USB (lines queued for loop)" "grep -q 'if (flashDrainPpg && !inWriter()) ppgService(hrDet.motion);' '$F' && grep -q 'if (inWriter()) { wrLogPush(line); return; }' '$F' && grep -q 'wrLogDrain();' '$F'"
chk "0.9.15 A-01: the watchdog is fed in the FIRST statements of setup() (a soft reset does not stop it) and inside the Serial wait" "awk '/^void setup\\(\\) \\{/{f=1;n=0;next} f&&/^  [a-zA-Z]/{n++; if(n==1&&\$0!~/wdtSurvived = NRF_WDT->RUNSTATUS/)bad=1; if(n==2&&\$0!~/if \\(wdtSurvived\\) wdtFeed\\(\\);/)bad=1; if(n==2)exit} END{exit bad}' '$F' && grep -q 'while (!Serial && millis() < 3000) { wdtFeed(); delay(10); }' '$F'"
chk "0.9.15 A-01: GPREGRET2 cleared only after the heal state is saved and the RAM marker consumed" "awk '/if \\(HB.marker\\) healSave\\(\\);/{a=NR} /hg_mk_consumed\\(&NI.mk\\);/{b=NR} /if \\(gpregret2Read\\(\\)\\) gpregret2Write\\(0\\);/{c=NR} END{exit !(a && b && c && a < b && b < c)}' '$F' && [ \$(grep -c 'gpregret2Write(0)' '$F') -eq 1 ]"
chk "0.9.15 A-04/A-06: no Adafruit_SPIFlashBase path (unbounded waits, swallowed errors): no qflash., no waitUntilReady, no readStatus" "! grep -q 'qflash\\.' '$F' && ! grep -q 'waitUntilReady()' '$F' && ! grep -q 'readStatus()' '$F' && grep -q 'flashErr(.r., &flashRdErr); return LFS_ERR_IO;' '$F' && grep -q 'flashErr(.p., &flashPrErr); return LFS_ERR_IO;' '$F'"
chk "0.9.15 A-05: deep power-down (0xB9) only in the fault-injection command and right before System OFF (0.9.16 hgSystemOff)" "[ \$(grep -c 'runCommand(0xB9)' '$F') -eq 2 ] && [ \$(grep 'runCommand(0xB9)' '$F' | grep -c 'flashWake()) qspiTr.runCommand(0xB9)') -eq 2 ] && awk '/^static void hgSystemOff/{f=1} f&&/runCommand\\(0xB9\\)/{ok=1} f&&/^}/{exit} END{exit !ok}' '$F'"
chk "0.9.15 A-03: writer task at priority 0 (time slicing is off); 0.9.16: an app-side guarded call with I/O progress counts as a check-in (hg_sup_step)" "grep -q 'xTaskCreate(wrTaskFn, \"logw\", 1536, NULL, TASK_PRIO_LOWEST' '$F' && grep -q 'if (fsOpC\\[k\\] != HG_FID_NONE && fsOpLoop\\[k\\]) {' '$F' && grep -q 'hg_sup_step(&SUP, &in, &o);' '$F'"
chk "0.9.15 A-14: VBAT never sampled during a buzz, low mode through the 3-in-a-row filter" "grep -q 'float v = buzz ? NAN : readVbat();' '$F' && grep -q 'if (vs == HG_VBAT_ENTER_LOW) {' '$F'"
chk "0.9.15 A-09/A-10: quick_boots only from hg_quick_boots_next (user resets are not evidence)" "[ \$(grep -c 'bootf.quick_boots = ' '$F') -eq 4 ] && grep -q 'bootf.quick_boots = hg_quick_boots_next(bootf.quick_boots, rstClass' '$F'"
chk "0.9.16 D.4: the watchdog reload register is written in ONE place (wdtHwFeed); after boot only the supervisor (fsDogCb) and the System OFF path call it" "[ \$(grep -c 'WDT_RR_RR_Reload' '$F') -eq 1 ] && grep -q 'static inline void wdtHwFeed() { NRF_WDT->RR\\[0\\] = WDT_RR_RR_Reload; }' '$F' && [ \$(grep -c 'wdtHwFeed()' '$F') -eq 5 ] && grep -q 'if (o.feed) wdtHwFeed();' '$F' && grep -q 'static inline void wdtFeed() { appBeatMs = millis(); if (!supOn) wdtHwFeed(); }' '$F'"
chk "0.9.16 D.1: the journal STARTED entry is written (bgBoot) before the screen, sensors, InternalFS, storage and BLE start" "awk '/^static void appSetup\\(\\) \\{/{f=1} f&&/^  bgBoot\\(\\);/{b=NR} f&&/CPS\\(CP_S_SCREEN\\);/{sc=NR} f&&/ifsHealBoot\\(mkF/{i=NR} f&&/else storageInit\\(\\);/{st=NR} f&&/else bleSetup\\(\\);/{bl=NR} END{exit !(b && b < sc && sc < i && i < st && st < bl)}' '$F'"
chk "0.9.16 the screen and the motor come up before storage (splash + power-up pattern), the rest rung goes off before any file system call" "awk '/^static void appSetup\\(\\) \\{/{f=1} f&&/bgSplash\\(\\);/{a=NR} f&&!p&&/probeDev\\(d\\)/{p=NR} f&&/if \\(BGP.rest\\) bgRest\\(\\);/{r=NR} f&&/vibrate\\(PAT_PWRUP\\);/{v=NR} f&&/else storageInit\\(\\);/{st=NR} END{exit !(a && a < p && p < r && r < v && v < st)}' '$F'"
chk "0.9.16 A-11: the app runs in its own task with a 12 KB static stack; the core loop task suspends itself" "grep -q '#define HG_APP_STACK_WORDS 3072u' '$F' && grep -q 'xTaskCreateStatic(appTaskFn, \"hgapp\", HG_APP_STACK_WORDS' '$F' && grep -q 'vTaskSuspend(NULL);' '$F' && grep -q '__wrap_vApplicationStackOverflowHook' '$F' && grep -q '__wrap_vApplicationMallocFailedHook' '$F'"
chk "0.9.16 A-24: an assert outside any guarded file call is a named soft reset (ASSERT), never an FS-HEAL marker; heal ignores fid none" "grep -q 'if (fsOp == HG_FID_NONE) bgSoftReset(HG_BG_RC_ASSERT);' '$F' && grep -q 'if (b->fid == HG_FID_NONE) return;' \$(dirname '$F')/hg_fw_heal.c"
chk "0.9.16/0.9.17 hgSystemOff only from the rest rung, the USB pwroff command (armed) and the wearer's confirmed power-off; each writes its journal mark first" "[ \$(grep -c 'hgSystemOff(\"' '$F') -eq 3 ] && grep -B1 'hgSystemOff(\"pwroff command\");' '$F' | grep -q 'hg_bg_mark(HG_BG_T_CLEAN)' && grep -B1 'hgSystemOff(\"power-off by the wearer\");' '$F' | grep -q 'hg_bg_mark(HG_BG_T_CLEAN)' && grep -q 'case HG_UI_E_PWR_CONFIRM: pwrOffNow(1); break;' '$F' && awk '/^static void bgRest\\(\\)/{f=1} f&&/hg_bg_mark\\(HG_BG_T_REST\\)/{m=NR} f&&/hgSystemOff\\(\"boot guard rest\"\\)/{o=NR} END{exit !(m && o && m < o)}' '$F'"
chk "0.9.16 BLE off is honoured: the runtime BLE entry points check bleOn (bleReady, advertising, INFO, STATUS, EVENTS, UART input, battery service, record flag)" "grep -q 'static bool bleReady() { return bleOn && ' '$F' && grep -q 'if (!advKick || !bleOn) return;' '$F' && [ \$(grep -c '^  if (!bleOn) return;' '$F') -eq 3 ] && grep -q 'while (bleOn && bleuart.available())' '$F' && grep -q 'if (bleOn) blebas.write' '$F' && grep -q 'if (bleOn) hgEvents.write' '$F' && grep -q 'if (bleOn && Bluefruit.connected()) r->flags' '$F' && grep -q 'if (!bleOn || !Bluefruit.connected()) return' '$F'"
chk "0.9.17 one UI owner: the button line is read only by the hgui engine (uiStep) and the System OFF release wait" "[ \$(grep -c 'digitalRead(PIN_BTN)' '$F') -eq 2 ] && grep -q 'hg_ui_sample(&UI, digitalRead(PIN_BTN) == LOW, now);' '$F'"
chk "0.9.17 one motor owner: GO written only by the sequencer driver (drvGo) and the boot-only vibrate(); vibrate() refuses once hgui runs and is called only by the power-up and rest patterns" "[ \$(grep -c 'i2cWriteReg8(0x5A, 0x0C, 1)' '$F') -eq 2 ] && grep -q 'if (!hasDrv || uiTaskOn) return;' '$F' && [ \$(grep -c '^  vibrate(' '$F') -eq 2 ]"
chk "0.9.17 the tick is played by hgui on press-DOWN, before the event reaches the app" "awk '/^static void uiStep/{f=1} f&&/HG_UI_E_DOWN/{d=NR} f&&/HG_HP_TICK/{t=NR} f&&/uiOut\\(&e\\)/{o=NR} f&&/^}/{exit} END{exit !(d && t && o && d < t && t < o)}' '$F'"
chk "0.9.17 a press reaches the frozen guardian only through uiShort / uiHelp (honest input, every press)" "[ \$(grep -c 'hg_fw_button(' '$F') -eq 2 ] && grep -q 'hg_fw_button(&FW, 1);' '$F' && grep -q 'hg_fw_button(&FW, 2);' '$F'"
chk "0.9.17 owner decisions: HELP 3 s, cancel lock 10 s, off prompt 5 s, blocked 60 s after HELP (demo-b7u), mid presses do nothing" "grep -q 'define HG_UI_HELP_MS         3000' \$(dirname '$F')/hg_fw_ui.h && grep -q 'define HG_UI_HELP_LOCK_MS    10000' \$(dirname '$F')/hg_fw_ui.h && grep -q 'define HG_UI_OFF_TIMEOUT_MS  5000' \$(dirname '$F')/hg_fw_ui.h && grep -q 'define HG_UI_OFF_AFTER_HELP_MS 60000u' \$(dirname '$F')/hg_fw_ui.h && grep -q 'no action (owner decision)' '$F'"
chk "0.9.17 owner decision: the planner runs Her Day only (no clock-driven generic nudges) and the frozen bedtime tip is neither shown nor felt" "grep -q 'in->herday_only = 1;' '$F' && grep -q 'if (scr == HG_SCR_NUDGE) scr = HG_SCR_OK;' '$F' && grep -q 'if (o->screen == HG_SCR_NUDGE && o->state == HG_ST_OK) return HG_HP_NONE;' '$F'"
chk "0.9.17 the ladder + gauge only read the frozen guardian (no step / command / init / button, no write to G)" "! grep -Eq 'hg_guardian_(step|cmd|init)\\(|hg_fw_button\\(|hg_fw_minute\\(' \$(dirname '$F')/hg_fw_ladder.c && ! grep -Eq 'G\\.[a-z_]+ *=[^=]' \$(dirname '$F')/hg_fw_ladder.c && grep -q 'hg_ga_lines(G.a_base, G.a_base_n, G.m_drink, G.m_cool, &GL);' '$F'"
chk "0.9.17 TWIM0 shared by two tasks: every sketch I2C transfer takes the mutex" "[ \$(grep -c 'I2cLock l; return l.ok && hg_i2c_' '$F') -eq 3 ] && [ \$(grep -Ec 'hg_i2c_(write|read|write_read)\\(' '$F') -eq 3 ]"
[ $fail = 0 ] && echo "TEST_STATIC_09: PASS" || { echo "TEST_STATIC_09: FAIL"; exit 1; }
